package android.os;import java.util.*;public class Handler {public interface Callback{boolean handleMessage(Message m);}public List<Message> pending=new ArrayList<>();public Handler(){}public Handler(Looper l,Callback c){}public Message obtainMessage(int w,Object o){return obtainMessage(w,0,0,o);}public Message obtainMessage(int w,int a,int b,Object o){Message m=new Message();m.what=w;m.arg1=a;m.arg2=b;m.obj=o;return m;}public void sendMessage(Message m){pending.add(m);}public void sendMessageDelayed(Message m,long d){pending.add(m);}public boolean hasMessages(int w){for(Message m:pending)if(m.what==w)return true;return false;}public void removeMessages(int w){pending.removeIf(m->m.what==w);}}
